const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const mountIsa = ee.Geometry.Point([139.4917, -20.7274]); // Mount Isa, QLD
  const townsville = ee.Geometry.Point([146.7781, -19.2643]); // Townsville, QLD

  // Define date range
  const startDate = '2019-01-27';
  const endDate = '2019-02-10';

  // Load GPM IMERG rainfall data
  const rainfall = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .select('precipitationCal'); // precipitation in mm

  const imgCount = rainfall.size().getInfo();
  console.log(`GPM Images found: ${imgCount}`);

  if (imgCount === 0) {
    console.log('No GPM data found. Trying TRMM...');
    // Fallback to TRMM
    const trmm = ee.ImageCollection('TRMM/3B42')
      .filterDate(startDate, endDate)
      .select('precipitation');
    const trmmCount = trmm.size().getInfo();
    console.log(`TRMM Images found: ${trmmCount}`);

    if (trmmCount === 0) {
      console.log('No rainfall data for Jan 27 - Feb 10, 2019');
      console.log('<answer>C1</answer>');
      return;
    }

    // Use TRMM (already in mm)
    const totalRainfallTRMM_Isa = trmm.reduce(ee.Reducer.sum())
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: mountIsa,
        scale: 5000,
        maxPixels: 1e9
      })
      .get('precipitation')
      .getInfo();

    const totalRainfallTRMM_Towns = trmm.reduce(ee.Reducer.sum())
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: townsville,
        scale: 5000,
        maxPixels: 1e9
      })
      .get('precipitation')
      .getInfo();

    const isaRainfallCm = totalRainfallTRMM_Isa / 10;
    const townsRainfallCm = totalRainfallTRMM_Towns / 10;

    console.log(`Mount Isa total rainfall: ${isaRainfallCm.toFixed(2)} cm`);
    console.log(`Townsville total rainfall: ${townsRainfallCm.toFixed(2)} cm`);

    if (totalRainfallTRMM_Isa === null || totalRainfallTRMM_Towns === null) {
      console.log('<answer>C3</answer>');
      return;
    }

    if (isaRainfallCm > 65 && townsRainfallCm > 65) {
      console.log('Both regions exceeded 65 cm');
      console.log('<answer>A</answer>');
    } else {
      console.log('At least one region did not exceed 65 cm');
      console.log('<answer>B</answer>');
    }
    return;
  }

  // Process GPM data (convert mm to cm)
  const totalRainfall_Isa = rainfall.reduce(ee.Reducer.sum())
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: mountIsa,
      scale: 5000,
      maxPixels: 1e9
    })
    .get('precipitationCal')
    .getInfo();

  const totalRainfall_Towns = rainfall.reduce(ee.Reducer.sum())
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: townsville,
      scale: 5000,
      maxPixels: 1e9
    })
    .get('precipitationCal')
    .getInfo();

  // Convert mm to cm
  const isaRainfallCm = totalRainfall_Isa / 10;
  const townsRainfallCm = totalRainfall_Towns / 10;

  console.log(`Mount Isa total rainfall: ${isaRainfallCm.toFixed(2)} cm`);
  console.log(`Townsville total rainfall: ${townsRainfallCm.toFixed(2)} cm`);

  if (totalRainfall_Isa === null || totalRainfall_Towns === null || 
      isNaN(isaRainfallCm) || isNaN(townsRainfallCm)) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (isaRainfallCm > 65 && townsRainfallCm > 65) {
    console.log('Both regions exceeded 65 cm rainfall');
    console.log('<answer>A</answer>');
  } else {
    console.log('At least one region did not exceed 65 cm');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
